import json
with open('/app/resources/treasury_bulletin_1990_09.json') as f:
    data = json.load(f)
print('Keys:', list(data.keys()))
if 'pages' in data:
    print('Number of pages:', len(data['pages']))
    for i, page in enumerate(data['pages'][:6]):
        print(f'Page {i}:', type(page), str(page)[:200] if page else None)
elif isinstance(data, dict):
    for k in list(data.keys())[:10]:
        print(f'{k}:', type(data[k]))
